"""Generate Python constants from the Lean-emitted JSON specification."""
from __future__ import annotations

import json
from pathlib import Path
from pprint import pformat

HERE = Path(__file__).resolve().parent
SPEC = HERE / "formal_spec.generated.json"
OUTPUT = HERE / "formal_counts.py"


def render(spec: dict) -> str:
    payload = pformat(spec, sort_dicts=True, width=88)
    return (
        '"""Generated by generate_python.py from EISKKA.Bench001A. Do not edit."""\n'
        f"FORMAL_SPEC = {payload}\n"
        "SHAPE = FORMAL_SPEC['shape']\n"
        "COUNTS = FORMAL_SPEC['operation_ledger']\n"
    )


def main() -> None:
    spec = json.loads(SPEC.read_text(encoding="utf-8"))
    if spec.get("spec_id") != "EIS-KKA-BENCH-001A":
        raise SystemExit("unexpected formal spec id")
    OUTPUT.write_text(render(spec), encoding="utf-8")


if __name__ == "__main__":
    main()
